export type PracticeMode = "word-first" | "audio-first";
export type WordStatus = "new" | "learning" | "mastered";
export type Rating = "known" | "fuzzy" | "again";
export type WordEntry = { id:string; word:string; meaning:string; partOfSpeech:string; phonetic:string; example:string; translation:string; audioData?:string; status:WordStatus; createdAt:number; repetitions:number; correctStreak:number; reviewBox:number; reviewAtCount:number };
export type DailyStats = { answered:number; known:number; fuzzy?:number; again:number; newIntroduced:number; reviewIntroduced:number; seenIds?:string[] };
export type ActiveSession = { date:string; ids:string[]; seenIds:string[]; index:number; mode:PracticeMode; feedback:{wordId:string;rating:Rating;message?:string;undo?:unknown}|null; attempts?:Record<string,number>; deferredIds?:string[]; extraPractice?:boolean };
export type AppData = { version:1; reviewCount:number; words:WordEntry[]; studyDays:Record<string,DailyStats>; activeSession:ActiveSession|null; settings:{dailyGoal:number;dailyReviewGoal:number;speechRate:number;voiceURI:string} };
export function todayKey(date?:Date):string;
export function emptyDailyStats():DailyStats;
export function createInitialData():AppData;
export const MASTERY_STREAK:number;
export function isDue(word:WordEntry,count:number):boolean;
export function createSession(data:AppData,date?:string,extraPractice?:boolean):ActiveSession;
export function answer(data:AppData,wordId:string,rating:Rating,date?:string):AppData;
export function undoAnswer(data:AppData):AppData;
export function regradeAnswer(data:AppData,rating:Rating):AppData;
export function continueSession(data:AppData):AppData;
export function decodeAppData(raw:string|object|null):AppData|null;
export function lookupStarterWord(word:string):Pick<WordEntry,"meaning"|"partOfSpeech"|"phonetic"|"example"|"translation">|undefined;
